<template>
  <div class="screen-input-wrapper">
    <div class="input-container">
      <div style="flex: 1; position: relative;">
        <input v-model="inputValue" :type="type" :placeholder="placeholder" :disabled="disabled" :readonly="readonly"
          :maxlength="maxlength" class="screen-input" :class="[`${size}_input`, { 'has-stepper': showStepper }]" @input="handleInput"
          @change="handleChange" @focus="handleFocus" @blur="handleBlur" />
        <div v-if="showStepper" class="stepper-controls">
          <button class="stepper-btn stepper-up" :disabled="disabled || readonly" @click="handleStepUp">
            <svg viewBox="0 0 12 12" width="12" height="12">
              <path d="M6 3 L9 8 L3 8 Z" fill="currentColor" />
            </svg>
          </button>
          <button class="stepper-btn stepper-down" :disabled="disabled || readonly" @click="handleStepDown">
            <svg viewBox="0 0 12 12" width="12" height="12">
              <path d="M6 9 L9 4 L3 4 Z" fill="currentColor" />
            </svg>
          </button>
        </div>
      </div>
      <div v-if="suffix" class="input-suffix">{{ suffix }}</div>
    </div>
  </div>
</template>

<script setup>
import { ref, watch } from 'vue'

const props = defineProps({
  modelValue: {
    type: [String, Number],
    default: ''
  },
  size: {
    type: String,
    default: ''
  },
  suffix: {
    type: String,
    default: ''
  },
  type: {
    type: String,
    default: 'text'
  },
  valueType: {
    type: String,
    default: 'string', // 'string' | 'number'
    validator: (value) => ['string', 'number'].includes(value)
  },
  placeholder: {
    type: String,
    default: '请输入'
  },
  disabled: {
    type: Boolean,
    default: false
  },
  readonly: {
    type: Boolean,
    default: false
  },
  maxlength: {
    type: [String, Number],
    default: undefined
  },
  min: {
    type: Number,
    default: undefined
  },
  max: {
    type: Number,
    default: undefined
  },
  precision: {
    type: Number,
    default: undefined
  },
  showStepper: {
    type: Boolean,
    default: false
  },
  step: {
    type: Number,
    default: 1
  }
})

const emit = defineEmits(['update:modelValue', 'input', 'change', 'focus', 'blur'])

const inputValue = ref(props.modelValue)

watch(() => props.modelValue, (newVal) => {
  inputValue.value = newVal
})

// 格式化数字值
const formatNumber = (value) => {
  if (value === '' || value === null || value === undefined) {
    return ''
  }

  let num = parseFloat(value)

  if (isNaN(num)) {
    return ''
  }

  // 应用精度
  if (props.precision !== undefined) {
    num = parseFloat(num.toFixed(props.precision))
  }

  // 应用最小值限制
  if (props.min !== undefined && num < props.min) {
    num = props.min
  }

  // 应用最大值限制
  if (props.max !== undefined && num > props.max) {
    num = props.max
  }

  return num
}

const handleInput = (e) => {
  let value = e.target.value

  if (props.valueType === 'number') {
    // 数字类型：允许输入数字、小数点、负号
    if (value && !/^-?\d*\.?\d*$/.test(value)) {
      e.target.value = inputValue.value
      return
    }
    emit('update:modelValue', value === '' ? '' : value)
    emit('input', value === '' ? '' : value)
  } else {
    emit('update:modelValue', value)
    emit('input', value)
  }
}

const handleChange = (e) => {
  let value = e.target.value

  if (props.valueType === 'number' && value !== '') {
    value = formatNumber(value)
    inputValue.value = value
    emit('update:modelValue', value)
    emit('change', value)
  } else {
    emit('change', value)
  }
}

const handleFocus = (e) => {
  emit('focus', e)
}

const handleBlur = (e) => {
  emit('blur', e)
}

// 步进控制方法
const handleStepUp = () => {
  if (props.disabled || props.readonly) return

  let currentValue = inputValue.value === '' ? 0 : parseFloat(inputValue.value)
  if (isNaN(currentValue)) currentValue = 0

  let newValue = currentValue + props.step

  // 应用最大值限制
  if (props.max !== undefined && newValue > props.max) {
    newValue = props.max
  }

  // 应用精度
  if (props.precision !== undefined) {
    newValue = parseFloat(newValue.toFixed(props.precision))
  }

  inputValue.value = newValue
  emit('update:modelValue', newValue)
  emit('change', newValue)
}

const handleStepDown = () => {
  if (props.disabled || props.readonly) return

  let currentValue = inputValue.value === '' ? 0 : parseFloat(inputValue.value)
  if (isNaN(currentValue)) currentValue = 0

  let newValue = currentValue - props.step

  // 应用最小值限制
  if (props.min !== undefined && newValue < props.min) {
    newValue = props.min
  }

  // 应用精度
  if (props.precision !== undefined) {
    newValue = parseFloat(newValue.toFixed(props.precision))
  }

  inputValue.value = newValue
  emit('update:modelValue', newValue)
  emit('change', newValue)
}
</script>

<style scoped>
.screen-input-wrapper {
  width: 100%;
  margin-bottom: 20px;
}

.input-container {
  display: flex;
  align-items: center;
}

.screen-input {
  font-family: "SourceHanSansSC 微软雅黑";

  width: 100%;
  height: 40px;
  padding: 0 15px;
  font-size: 16px;
  color: #FFFFFF;
  background: rgba(15, 96, 170, 0.3);
  border: 1px solid #5cb9f7;
  border-radius: 4px;
  outline: none;
  transition: all 0.3s ease;
  box-sizing: border-box;
}

.screen-input.has-stepper {
  padding-right: 30px;
}

.screen-input.small_input {
  height: 28px;
  margin-top: 5px;
}

.input-suffix {
  font-family: "SourceHanSansSC 微软雅黑";

  width: 40px;
  font-size: 14px;
  color: rgba(255, 255, 255, 1);
  text-align: center;
  flex-shrink: 0;
}

.screen-input::placeholder {
  color: rgba(255, 255, 255, 0.5);
}

.screen-input:hover:not(:disabled) {
  border-color: rgba(255, 255, 255, 0.4);
  background: rgba(15, 96, 170, 0.4);
}

.screen-input:focus {
  border-color: rgba(64, 158, 255, 0.8);
  background: rgba(15, 96, 170, 0.5);
  box-shadow: 0 0 8px rgba(64, 158, 255, 0.3);
}

.screen-input:disabled {
  cursor: not-allowed;
  opacity: 0.6;
  background: rgba(15, 96, 170, 0.2);
}

.screen-input:readonly {
  cursor: default;
  background: rgba(15, 96, 170, 0.25);
}

.stepper-controls {
  position: absolute;
  right: 5px;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.stepper-btn {
  width: 20px;
  height: 17px;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(15, 96, 170, 0.5);
  border: 1px solid rgba(92, 185, 247, 0.6);
  border-radius: 2px;
  color: #5cb9f7;
  cursor: pointer;
  transition: all 0.3s ease;
  outline: none;
}

.stepper-btn:hover:not(:disabled) {
  background: rgba(15, 96, 170, 0.7);
  border-color: rgba(92, 185, 247, 0.9);
  color: rgba(92, 185, 247, 1);
}

.stepper-btn:active:not(:disabled) {
  background: rgba(15, 96, 170, 0.8);
}

.stepper-btn:disabled {
  cursor: not-allowed;
  opacity: 0.4;
  border-color: rgba(92, 185, 247, 0.3);
  color: rgba(92, 185, 247, 0.3);
}

.stepper-up svg {
  transform: translateY(-1px);
}

.stepper-down svg {
  transform: translateY(1px);
}

</style>
